648	// 外部修改旧版或新版查询中的时间，不得改变替代交接点；新版到期后旧版不恢复生效。
649	func TestReplacementHandoffImmuneToViewMutation(t *testing.T) {
650		now, setNow := fixedClock(at(0))
651		b := NewBook(WithClock(now))
652		must := func(r RegisterRequest) {
653			t.Helper()
654			if err := b.RegisterVersion(r); err != nil {
655				t.Fatalf("register: %v", err)
656			}
657		}
658		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 1, Start: at(0), End: atPtr(100)})
659		must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 1, Start: at(40), End: atPtr(60), Replaces: "old"})
660	
661		views, _ := b.ItemVersions("seat")
662		for i := range views {
663			if views[i].VersionID == "old" {
664				*views[i].End = at(1000)
665				*views[i].EffectiveEnd = at(1000)
666			}
667			if views[i].VersionID == "new" {
668				*views[i].End = at(1000)
669				*views[i].EffectiveEnd = at(1000)
670			}
671		}
672	
673		again, _ := b.ItemVersions("seat")
674		for _, v := range again {
675			switch v.VersionID {
676			case "old":
677				if v.End == nil || !v.End.Equal(at(100)) {
678					t.Fatalf("old registered end changed: %v", v.End)
679				}
680				if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(40)) {
681					t.Fatalf("handoff point changed: %v", v.EffectiveEnd)
682				}
683			case "new":
684				if v.End == nil || !v.End.Equal(at(60)) {
685					t.Fatalf("new registered end changed: %v", v.End)
686				}
687				if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(60)) {
688					t.Fatalf("new effective end changed: %v", v.EffectiveEnd)
689				}
690			}
691		}
692	
693		// 新版到期后，旧版仍止于交接点，不能恢复生效
694		setNow(at(70))
695		out, _ := b.Quote(QuoteRequest{RequestID: "q-old", ItemID: "seat", VersionID: "old", Quantity: 1})
696		if out.Confirmed || out.Reason != ReasonVersionExpired {
697			t.Fatalf("superseded old must not revive: %+v", out)
698		}
699	}
700	
701	// 未提供结束时间且未被替代的版本持续有效，两种结束时间都为空；
702	// 之后被替代，登记结束仍为空，实际结束显示交接点。
703	func TestOpenEndedKeepsNilRegisteredEnd(t *testing.T) {
704		b := NewBook()
705		must := func(r RegisterRequest) {
706			t.Helper()
707			if err := b.RegisterVersion(r); err != nil {
708				t.Fatalf("register: %v", err)
709			}
710		}
711		must(RegisterRequest{ItemID: "seat", VersionID: "old", UnitPrice: 1, Start: at(0)})
712		views, _ := b.ItemVersions("seat")
713		if views[0].End != nil || views[0].EffectiveEnd != nil {
714			t.Fatalf("open-ended version must report nil ends: %+v", views[0])
715		}
716	
717		must(RegisterRequest{ItemID: "seat", VersionID: "new", UnitPrice: 1, Start: at(40), Replaces: "old"})
718		views, _ = b.ItemVersions("seat")
719		// 即使调用方给返回结果中的登记结束塞了值，再次查询仍应为 nil
720		for i := range views {
721			if views[i].VersionID == "old" {
722				late := at(99)
723				views[i].End = &late
724				*views[i].EffectiveEnd = at(99)
725			}
726		}
727		again, _ := b.ItemVersions("seat")
728		for _, v := range again {
729			if v.VersionID == "old" {
730				if v.End != nil {
731					t.Fatalf("registered end must stay nil after replacement: %v", v.End)
732				}
733				if v.EffectiveEnd == nil || !v.EffectiveEnd.Equal(at(40)) {
734					t.Fatalf("effective end should show handoff: %v", v.EffectiveEnd)
735				}
736			}
737		}
738	}
